insert into consultants (id, full_name, kind, bio, languages, region, day_rate_band, dataset) values
  ('1ad9dfe8-4f87-5418-ac4b-1dd38c89a738','Anton Verheyden','internal','Founder of Hautel Agency (Brecht). Full commercial and creative lead: strategy, sales, account management, project coordination, creative direction, on-set photography and video, drone. 30+ hotels in Benelux and Germany; revenue in DE 2024-26, LU and Cameroon 2026. Testimonials from Crowne Plaza Antwerp, Hotel Indigo Brussels, IHG Dubai, Kingsman, FCM Travel. Source: FIT masterfile 2.1/2.6, website brief §6.','{nl,fr,en,de}','Brecht / Antwerp, BE',null,'real'),
  ('4af8cfba-2bdc-58b5-9071-e65b021fb726','Aaron Cimanga','internal','Head of Creative / Creative Director at Hautel Agency. Leads the full creative production process: ideation, concept development, production, editing, coaching and creative direction. Cinematography background at La Cambre (Brussels) and short film. Owns shotlists and visual proposals per property for hotel-group shoots. Source: website brief §6, Pandox project briefing step 5.','{fr,en}','Brussels, BE',null,'real'),
  ('b8d5c316-f151-5c3f-b374-b1861cc629ba','Boyan Georgiev','internal','FPV drone pilot and aerial cinematographer for Hautel Agency; built his own FPV drone; fly-throughs and scale shots of properties. Videographer on hotel shoots. Technical lead for the Hautel Intelligence ISS work packages. Source: website brief §6, Cocoon videography agreement.','{bg,en,nl}','Antwerp, BE',null,'real'),
  ('e770aa1b-c83e-58aa-9078-cc78ab221db5','Lize Rubens','freelancer','Freelance creative under Hautel agreement (8 Dec 2025): videography, editing, photography, social media, communication, online marketing, creative direction and advertising. Works exclusively in Hautel''s name for hospitality clients. Source: Freelanceovereenkomst Hautel Agency x Lize Rubens.','{nl,en}','Antwerp, BE',null,'real'),
  ('223f23fc-712f-5de4-8f6a-660f6e4ae053','Bram Nouwen (Collexi)','freelancer','Web designer and developer, Hasselt. Engaged for the full redesign of hautel.agency including the Hautel Intelligence division (NDA 11 Jun 2026). Source: Hautel_NDA_Bram_Nouwen.','{nl,en}','Hasselt, BE',null,'real'),
  ('90450048-6b11-5153-8309-57a00696abc4','The Timechamber (Vintage 106 BV)','agency','Production studio and performance agency in Ranst (Hannes Vermost, Philippe Van Doninck). Corporate video production with itemised pricing (concept €250, scouting €150, planning €150, shoot day cameraman+assistant+kit €1,350, actors/VO €350, edit €1,000, sound €450, grade €350, revisions €200, export €100). Separate partner proposal (4 Sep 2026) for end-to-end tracking: GA4, GTM + Consent Mode v2, Meta Pixel/CAPI, booking-engine and restaurant/spa/MICE conversions, Looker Studio; package €7,950, campaign management €1,450/month (12-month minimum), landing pages €1,750 each. Partner tariffs net for Hautel. Source: quote 2026/35 and Voorstel Performance Tracking.','{nl,en}','Ranst / Antwerp, BE','1350 per production day; 1450/month campaign mgmt','real'),
  ('46612694-9959-5aaa-90d7-3236138c9949','RADAR (Charlotte Joos)','agency','Meta Ads specialist (radarsocials.com). Strategy and funnel, lead campaigns to form/Calendly, retargeting, per-market targeting for BE/LU/DE/FR, Pixel + Conversions API, weekly optimisation, monthly reporting. Management €550/month plus €300-500 media; no setup fee; 3-6 month term. Partners with a Google/LinkedIn/TikTok ads specialist (Google from ~€300/month). Source: Offerte Meta Ads 21 Sep 2026.','{nl,en,fr,de}','Belgium','550/month management','real'),
  ('2685d09e-4405-514e-95d4-f8b6dcd8cafd','Videntra (Alexander Baert)','agency','Alexander Baert: Co-Founder & Commercial Director of Hautel Intelligence, CEO of Videntra (agentic OS for communication). Drives growth via commercial strategy and technology-driven execution; signs Hautel agreements as Sales Director. Joint Videntra x Hautel market approach. Source: website brief §6, Samenwerkingsovereenkomst.','{nl,en}','Belgium',null,'real'),
  ('d698c448-e517-55b9-9961-d7024f0a2d75','Nikita Nagurniy','freelancer','Tech Lead / Technical & Data Analyst for Hautel Intelligence (UA). Builds and runs voice agents on Retell AI with n8n automation, Airtable, Twilio/Telnyx telephony; hotel-tech-stack integrations (custom PMS work scoped hours to weeks); knowledge bases (5 min); QA 1-2 days per hotel; measures AI impact. Cost model: ~$0.145 per 2-minute call, 20 concurrent calls. Source: website brief §6, Questions for Nikita.','{uk,en}','remote (UA)',null,'real'),
  ('5b31ed87-fd04-5529-bc67-8f0f758a0d33','Ragnhild Vårin Irtun Moe','freelancer','Hospitality professional, Nordics (NO); co-founder track for Hautel Intelligence / Guesti as Head of Sales & Strategy: ICP, pricing model, outreach playbook, discovery calls, demos, negotiation, CRM pipeline, reporting, onboarding. Luxury hotel operations background incl. Forbes and AAA audit standards. Met Anton at EMCup Maastricht. Source: website brief §6, ragnhild_trajectory, Buddy AI CEO role definition.','{no,en}','Nordics (NO)',null,'real'),
  ('bca13b08-3468-5717-a5c0-9a3cd7cebd86','Amotek','agency','AI and automation build partner named alongside Videntra for the Build & Configuration step of Hautel Intelligence engagements. No agreement or scope document in the Drive. Source: website brief §1, §4, §12.','{}','Belgium',null,'real'),
  ('cdd94e2b-a612-58f3-abeb-7e5be54aed73','UPR','agency','Agency partner. Hautel works under contract via UPR for certain clients and joint commercial approaches are being explored and executed. No agreement in the Drive. Source: FIT masterfile 2.2; folder ''Case: UPR x Hautel''.','{}','Belgium',null,'real'),
  ('460096d6-80d4-5af0-ab40-0fb88d09f5aa','Anastasia Shalovinsky','internal','Marketing & communication intern (Thomas More, 18 May-12 Jun 2026, unpaid). Delivered Instagram highlights, 9 posts/reels, June content calendar (16 IG + 8 LinkedIn), TikTok account launch plan, all in Canva. Junior social content support. Source: Stagecontract, Werkplekscan, Stage Missies v3.','{nl,en}','Oostmalle / Antwerp, BE','unpaid internship','real')
