-- Real consultant roster reconstructed from the Hautel Company Drive, 28 Sep 2026 (dataset = 'real').
-- Source per row: 'Research & Development/WP1 - Architecture & Data Foundation/Real data (Drive)/Consultant Roster (from Drive, 28 Sep).md'.
-- day_rate_band is null where the Drive holds no tariff. Requires migration 004. Idempotent.
begin;
on conflict (id) do update set full_name=excluded.full_name, kind=excluded.kind, bio=excluded.bio, languages=excluded.languages, region=excluded.region, day_rate_band=excluded.day_rate_band, dataset='real';
on conflict (consultant_id, skill) do update set level=excluded.level, evidence=excluded.evidence;
commit;
